function safeURL(value,image){if(!value)return true;if(image&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value))return true;if(!image&&/^\/(?!\/)[^\s\\]*$/.test(value))return true;if(!image&&/^#[A-Za-z][\w:.-]*$/.test(value))return true;try{var u=new URL(value);return u.protocol==='https:'&&!/[\s\\]/.test(value)&&!u.username&&!u.password;}catch(e){return false;}}
